/**
 * Benchmark catalog — committed cross-repo mirror of
 * `Funds_DAG/configs/benchmark_universe.yaml`.
 *
 * The single source of truth is the YAML in Funds_DAG; we mirror it as
 * `mcp/data/benchmark_master.json` (generated by
 * `Funds_DAG/scripts/export_benchmark_master_json.py`, same cross-repo pattern as
 * the OpenAPI / capabilities mirror). This module loads the JSON at first use
 * and caches it for the lifetime of the Node process — benchmarks change rarely
 * and require a redeploy of this repo anyway, so a one-time read is the right
 * complexity ceiling. Empty / missing file → empty catalog (degrades to
 * "`BW-BENCH-*` ids pass through, aliases don't resolve"), never throws.
 *
 * Replaces the hardcoded `BENCHMARK_ALIASES` const that used to live in
 * `lib/dal/funds-zarr-reader.ts` (`benchmark_v2_followups.md` #1).
 */

import { existsSync, readFileSync } from "fs";
import { join } from "path";

export interface BenchmarkComponentRecord {
  source_kind: string;
  ref: string;
  weight: number;
}

export interface BenchmarkContextRecord {
  bw_bench_id: string;
  name: string;
  benchmark_kind: string;          // index_proxy | blend | peer_cohort | constructed_hedge
  aliases: string[];
  methodology: string;
  rebalance_schedule: string;
  observation_mode: string;        // reality | knowledge | system
  proxy: { source_kind: string; ref: string } | null;
  components: BenchmarkComponentRecord[];
  benchmark_context_version: string;
  notes: string;
}

interface BenchmarkCatalog {
  schema_version: string;
  n_contexts: number;
  /** alias_lower → bw_bench_id */
  aliases: Record<string, string>;
  /** bw_bench_id → full BenchmarkContext record */
  contexts: Record<string, BenchmarkContextRecord>;
}

const EMPTY: BenchmarkCatalog = {
  schema_version: "benchmark-master/1.0",
  n_contexts: 0,
  aliases: {},
  contexts: {},
};

let _cached: BenchmarkCatalog | null = null;

function _path(): string {
  return join(process.cwd(), "mcp", "data", "benchmark_master.json");
}

function _load(): BenchmarkCatalog {
  if (_cached) return _cached;
  const p = _path();
  if (!existsSync(p)) {
    _cached = EMPTY;
    return _cached;
  }
  try {
    const parsed = JSON.parse(readFileSync(p, "utf-8")) as Partial<BenchmarkCatalog>;
    _cached = {
      schema_version: parsed.schema_version ?? EMPTY.schema_version,
      n_contexts: parsed.n_contexts ?? Object.keys(parsed.contexts ?? {}).length,
      aliases: parsed.aliases ?? {},
      contexts: (parsed.contexts ?? {}) as Record<string, BenchmarkContextRecord>,
    };
    return _cached;
  } catch {
    _cached = EMPTY;
    return _cached;
  }
}

/** Test seam: reload the cached catalog from disk. */
export function _reloadBenchmarkCatalog(): BenchmarkCatalog {
  _cached = null;
  return _load();
}

/** Resolve an alias (case-insensitive) to a `bw_bench_id`, or null if unknown. */
export function lookupBenchmarkAlias(input: string): string | null {
  const cat = _load();
  const key = (input ?? "").trim().toLowerCase();
  if (!key) return null;
  return cat.aliases[key] ?? null;
}

/** Read the full `BenchmarkContext` record for a `bw_bench_id`, or null. */
export function getBenchmarkContext(bwBenchId: string): BenchmarkContextRecord | null {
  return _load().contexts[bwBenchId.toUpperCase()] ?? null;
}

/** All known `bw_bench_id`s in the committed catalog. */
export function listBenchmarkContexts(): BenchmarkContextRecord[] {
  return Object.values(_load().contexts);
}

/** Currently-loaded catalog metadata — useful for diagnostics endpoints. */
export function benchmarkCatalogMetadata(): { schema_version: string; n_contexts: number; path: string } {
  const cat = _load();
  return { schema_version: cat.schema_version, n_contexts: cat.n_contexts, path: _path() };
}
